# dsv4-cc-proxy — DeepSeek V4 的 Anthropic API 兼容性代理
#
# 本文件由 dsv4-cc-proxy 仓库的 .github/workflows/ci.yml 在打 tag 时渲染生成。
# 不要直接编辑 homebrew-tap 里的副本——改动会被下一次发布覆盖；
# 请修改 dsv4-cc-proxy 的 .github/templates/dsv4-cc-proxy.rb。
#
# Python 应用走 Homebrew 标准的 Virtualenv 模式：venv 建在 libexec，
# 依赖以 resource 块预取（pip 安装带 --no-deps，传递依赖必须齐全），
# 最后把 console script 链接进 bin。
#
# 依赖约束一旦变化，需在本地对渲染后的 formula 重跑
# `brew update-python-resources`，再把新的 resource 块同步回模板。
class Dsv4CcProxy < Formula
  include Language::Python::Virtualenv

  desc "Anthropic API compatibility proxy for running Claude Code on DeepSeek V4"
  homepage "https://github.com/HosheaLi/dsv4-cc-proxy"
  url "TARBALL_URL_PLACEHOLDER"
  sha256 "SHA256_PLACEHOLDER"
  license "MIT"

  depends_on "python@3.14"

  resource "anyio" do
    url "https://files.pythonhosted.org/packages/a9/d2/f4d173e22df740bc37b1db102b386ba719b66e95b0f0d751f556b387e6d2/anyio-4.15.1.tar.gz"
    sha256 "9f28306018cbd6d329e64a36d58256edff76dd996fe423bc957326e578b82a94"
  end

  resource "certifi" do
    url "https://files.pythonhosted.org/packages/a3/c2/24167ea9858356b47a87a50d39908bfdb72ceeefe0041586e704e5376b3a/certifi-2026.7.22.tar.gz"
    sha256 "741e2c3b351ddf169a738da9f2c048608ff7f2c5cc02f1ebc6b118bb090d5d55"
  end

  resource "click" do
    url "https://files.pythonhosted.org/packages/c7/0e/7fa0ef50764b67090eca4114772a2abf8b6148198475e54c660b97caeee6/click-8.5.0.tar.gz"
    sha256 "ba0d2089de75ea0310e2dde03160e6ca10009947fb95a182f9b54021bb272e34"
  end

  resource "h11" do
    url "https://files.pythonhosted.org/packages/01/ee/02a2c011bdab74c6fb3c75474d40b3052059d95df7e73351460c8588d963/h11-0.16.0.tar.gz"
    sha256 "4e35b956cf45792e4caa5885e69fba00bdbc6ffafbfa020300e549b208ee5ff1"
  end

  resource "httpcore" do
    url "https://files.pythonhosted.org/packages/06/94/82699a10bca87a5556c9c59b5963f2d039dbd239f25bc2a63907a05a14cb/httpcore-1.0.9.tar.gz"
    sha256 "6e34463af53fd2ab5d807f399a9b45ea31c3dfa2276f15a2c3f00afff6e176e8"
  end

  resource "httpx" do
    url "https://files.pythonhosted.org/packages/b1/df/48c586a5fe32a0f01324ee087459e112ebb7224f646c0b5023f5e79e9956/httpx-0.28.1.tar.gz"
    sha256 "75e98c5f16b0f35b567856f597f06ff2270a374470a5c2392242528e3e3e42fc"
